import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.DTwTvi8b.js";const q=JSON.parse('{"title":"0027 Paseo 插件：随 req-kit 一起发布，只通过 req api 工作","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0027-paseo-plugin.md","filePath":"reference/adr/0027-paseo-plugin.md","lastUpdated":null}'),r={name:"reference/adr/0027-paseo-plugin.md"};function d(s,e,l,n,c,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<div><h1 id="_0027-paseo-插件-随-req-kit-一起发布-只通过-req-api-工作" tabindex="-1">0027 Paseo 插件：随 req-kit 一起发布，只通过 req api 工作 <a class="header-anchor" href="#_0027-paseo-插件-随-req-kit-一起发布-只通过-req-api-工作" aria-label="Permalink to &quot;0027 Paseo 插件：随 req-kit 一起发布，只通过 req api 工作&quot;">​</a></h1><ul><li>状态：已采纳（建立在 <a href="./0026-machine-records-and-api">0026</a> 的需求索引和 <code>req api</code> 之上；不改变 <a href="./0003-script-engine-not-hub">0003</a>：流程仍由脚本引擎驱动）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>需求方和项目经理想在 Paseo 的网页端或手机上看到所有需求在哪一步、卡在哪里，并做确认方案、停止、继续这类操作，而不是在对话里问或在终端敲 <code>req</code>。Paseo 0.11 有完整的插件机制：界面（侧边栏、页面、工作区面板、按钮、命令中心）、daemon 侧的 RPC 和生命周期事件，同一份界面代码在桌面版、网页端和手机上运行。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>插件只做展示和管理，不参与流程</strong>：每个读取是一次 <code>req api</code>，每个管理操作是 <code>req api run &lt;approve|stop|resume|verify&gt;</code>，与在终端执行 <code>req &lt;命令&gt;</code> 完全相同。插件不读写状态文件，引擎仍是唯一修改需求状态的一方。不提供发起需求（需要在对话中对齐）、编辑需求说明或方案、修改配置、删除。</li><li><strong>随 req-kit 一起发布，从固定目录安装</strong>：插件源码在仓库的 <code>paseo-plugin/</code>，打进 <code>paseo-req-kit</code> 包。<code>req plugin install</code> 把当前版本的插件复制到 <code>~/.req-kit/paseo-plugin</code>，用 <code>paseo plugin install &lt;目录&gt;</code> 安装；之后每次启用版本（setup、upgrade、use）都刷新这个目录并 <code>paseo plugin reload</code>。这样插件版本总是和启用的 req-kit 一致，也不需要单独的 npm 包、网络或第二套发布配置。设计时曾考虑第二个 npm 包，Paseo 的目录安装让它变得不必要。</li><li><strong>插件总开关要人同意</strong>：Paseo 的 <code>pluginsEnabled</code> 默认关闭，插件是不受沙箱限制的代码。<code>req plugin install</code> 和安装脚本都先说明再询问，<code>--yes</code> / <code>--with-plugin</code> 表示同意；移除插件不改动总开关。</li><li><strong>只读模式</strong>：Paseo 的插件没有按用户区分的权限，能连上 daemon 的人都能操作。插件设置中的&quot;只读&quot;隐藏管理操作，daemon 侧也拒绝它们。</li><li><strong>只依赖 <code>req api</code> 的格式</strong>：插件通过本机配置目录的 <code>active.json</code> 找到启用的版本并运行它的 <code>req api</code>，不引用 req-kit 的内部代码；req-kit 太旧时插件给出升级提示。</li><li><strong>界面按 Paseo 的跨平台规则写</strong>：只用 React Native 组件和主题颜色，不用 DOM。插件的界面部分由 CI 用 Paseo 的 SDK 做类型检查（<code>paseo-plugin/</code> 的开发依赖），daemon 侧和 <code>req plugin</code> 有单元测试；界面效果需要在真实的 Paseo 中检查。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>新增 <code>req plugin install|status|remove</code>，安装脚本最后可选安装插件。</li><li>列表靠轮询刷新（默认 10 秒，可设置）；daemon 侧把短时间内的多个列表请求合并成一次 <code>req api list</code>。</li><li>步骤 agent 的&quot;需求&quot;按钮靠 req-kit 给步骤 agent 打的标签（<code>requirement-pipeline</code>）找到需求；工作区的&quot;需求&quot;按钮按目录匹配需求。</li><li><code>paseo-plugin/package.json</code> 的版本必须与 req-kit 相同（测试检查），<code>paseo-plugin.json</code> 的 Paseo 范围与 <code>reqKit.paseo</code> 相同。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0027-paseo-plugin.md">docs/adr/0027-paseo-plugin.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0027-paseo-plugin.md">在 GitHub 上编辑</a></p>',2)])])}const g=o(r,[["render",d]]);export{q as __pageData,g as default};
